const envelope = $json.body ?? $json;
const allowed = ['ads.budget.update', 'social.publish', 'sales.contact.send', 'crm.records.update'];
const action = envelope.action;
if (!action || action.status !== 'approved') {
  throw new Error('Agent Hub action is not approved');
}
if (!allowed.includes(action.tool)) {
  throw new Error(`Tool is not allowlisted: ${action.tool}`);
}
return [{
  json: {
    accepted: true,
    execution_id: `phase2-dry-run-${Date.now()}`,
    phase: 'dry-run',
    task_id: envelope.task_id,
    action_id: action.action_id,
    tool: action.tool,
    payload: action.payload ?? {},
    note: 'Phase 2 executor validates approved writes but does not perform external writes until credentials and per-tool mappings are configured.'
  }
}];
